INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gilligans-gold', 77460, '1984-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7hbo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4wl6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gilligan''s Gold', 'Gilligan''s Gold is a flick-screen platform game based on the arcade game Bagman consisting of three screens as you try to negotiate various levels of a mine to collect all the bags of gold scattered around the three screens. Trying to stop you are a couple of outlaws and if you touch one then you lose one of five lives. You must use the ladders and lifts to move up and down levels and if you fall down more than one level then you lose a life. Once you have a bag of gold you must drag it up to the top of the mine and put it in your wheelbarrow which can be moved anywhere on the top of the mine on any screen. Dragging a bag of gold slows you down but can be used to drop on the head of an outlaw. You can use a pick axe to dig through a yellow wall hiding a bag of gold and it can also can stun an outlaw for a few seconds but can only be used once. Moving about the screens are mine-carts and although if they hit you, you lose a life but you can ride them. Grab onto a hook and when a cart is beneath you drop on it. You can get off a cart at anytime.' FROM games WHERE igdb_id = 77460 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 77460 AND ge.slug = 'platform' ON CONFLICT DO NOTHING;
