INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('alchemist', 13944, '1984-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ksm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1ma6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alchemist', 'The player controls an alchemist who has been summoned to defeat an evil warlock. The game is set inside the warlock''s castle, with the game''s primary objective being finding four pieces of a magic scroll. This allows the alchemist to use the "Spell of Destruction" to defeat the warlock. The alchemist can transform into a golden eagle, requiring the use of spell energy. Transforming between the two is essential to completing the game. The alchemist can hurl lightning bolts and other spells, but the eagle form is required to negotiate steep hills or drops. The alchemist can only carry one item at a time and must consume food to keep stamina levels up. Movement, bumping into objects, or transforming depletes the character''s stamina. Fighting monsters also reduces the character''s stamina, although this can be mitigated by carrying an axe or sword.' FROM games WHERE igdb_id = 13944 ON CONFLICT (game_id, language_code) DO NOTHING;
