INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('indiana-jones-in-the-lost-kingdom', 25862, '1984-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co97rh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scikoz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indiana Jones in the Lost Kingdom', 'Indiana Jones in the Lost Kingdom is a puzzle video game developed by Michael J. Hanson and published by Mindscape for the Commodore 64. The game is based on the Indiana Jones series, and was released in North America around January 1985, while a U.K. version was released in March 1985. Gameplay requires the player to think like fictional archaeologist Indiana Jones to solve the puzzles of each level, as the game does not provide the player with any rules or gameplay information; the game''s cover advertised, "Nobody told Indiana Jones the rules. And no one will tell you." Indiana Jones in the Lost Kingdom features six levels played across a "Lost Kingdom." Playing as Indiana Jones, the player must solve a puzzle in each level to progress through the game. The player''s ultimate goal is to retrieve a valuable artifact that contains the secrets of a lost civilization, before Jones'' arch-rival, Ivar Reiss, can take it for himself. Indiana Jones is armed only with a mystical cane, and must battle against numerous enemies and perils throughout the game, including bats, monsters, steep cliffs, twisting mazes, and "killer snowflakes". Joystick movements vary between each level, requiring the player to relearn the control scheme throughout the game. A two-player option is also available. No rules or gameplay information is provided to the player, who is left to use logic and intuition to solve each puzzle, as Indiana Jones would. Solving each puzzle requires the player to pay close attention to subtle changes in each level''s surroundings or musical score, as well as other possibilities, testing the player''s "Indiana Jones Quotient" (IJQ). However, the game''s instruction manual does feature clues at the bottom of each page. Each clue is presented as a hieroglyphic, and must be deciphered by the player using a magic viewer, similar to 3D glasses. A "clue hotline" was also available for players, providing them with pre-recorded hints on how to finish each level.' FROM games WHERE igdb_id = 25862 ON CONFLICT (game_id, language_code) DO NOTHING;
