INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nutcraka', 'Cyril the Squirrel is due to start hibernating but has yet to collect and store all the nuts he needs to get through the winter. You play as Cyril in this platform game where the screen scrolls in both left and right directions when you move. The game is spread over eight levels and you must collect all the nuts on each level to move to the next level within a time limit.' FROM games WHERE igdb_id = 349629 ON CONFLICT (game_id, language_code) DO NOTHING;
