INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spatter', 40168, '1984-02-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5q8l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/e7noqfcmqkqgfcatbwbj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spatter', 'Spatter is a fast-moving maze-chase game in which the player takes on the role of a tricycle-pedalling child out collecting flowers, while trying to avoid collisions with the numerous enemies giving chase. Most of the maze paths are separated into two lanes, with a springy elastic fence separating them. This fence is the key to playing the game, as players can jump into it, allowing them to squeeze past oncoming enemies in the same lane. Also, enemies on the opposite side of the fence can be sent flying from the track. Solid blocks also feature, and these can be pushed into enemies to destroy them. Special bonus rounds feature after stages two, six, ten and fourteen. These rounds are platform-based, with the player trying to collect as many items of fruit as possible before heading up to the highest platform, to meet up with a friendly elderly lady who is waiting there. ''Fruit'' and ''Happy'' bonuses are then awarded.' FROM games WHERE igdb_id = 40168 ON CONFLICT (game_id, language_code) DO NOTHING;
