INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shirobara Renzoku Satsujin Jiken', '"The white rose is a blood curse... Its petals are soaked and stained red by blood. Someday, the bell will toll and all will be swept by ruin. When the white rose wilts, all evil and curses must disappear... A.M." Just one week after receiving this bizarre letter, the Hanayama family discovers a body at their mansion. You and your assistant return to get to the bottom of this case.' FROM games WHERE igdb_id = 353184 ON CONFLICT (game_id, language_code) DO NOTHING;
