INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fred', 'The game consists of 6 levels, on which you must obtain treasures and - of course - a map that allows you to leave the labyrinthine pyramid alive. You must avoid dangerous acid drops, mummies, spiders, vampires, etc. In order to defend yourself from those disagreeable enemies you have at your disposition a gun (with limited bullets), but some enemies are immune to guns, and you must jump or avoid them.' FROM games WHERE igdb_id = 25841 ON CONFLICT (game_id, language_code) DO NOTHING;
