INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pyramania', 'The game is set in a mysterious pyramid filled with traps and guarded by various evil beings. Players must skillfully maneuver through different levels, avoiding threats and solving puzzles to progress. The pyramid''s design is intricate, requiring players to think strategically to overcome obstacles and find the hidden treasures.' FROM games WHERE igdb_id = 379901 ON CONFLICT (game_id, language_code) DO NOTHING;
