INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blood ''n'' Guts', 'Blood ''n'' Guts immerses puts the player inside the body of a hypochondriac, following the accidental enlargement of a submarine. The player''s mission is to reassemble the submarine, which has broken into eight pieces scattered throughout the body, and escape through the eye.' FROM games WHERE igdb_id = 380107 ON CONFLICT (game_id, language_code) DO NOTHING;
