INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hurry Fox', 'When a mother fox''s kit becomes sick with a deadly disease, she sets out on a quest for the magic fried tofu that''s said to be able to cure it. Hurry Fox is a traditional text adventure game, tasking players with meeting characters and solving problems on their way to saving the young kit. Unlike many other text adventure games, movement in this game is controlled via the arrow keys instead of typing in directions and the available exits are always printed onscreen.' FROM games WHERE igdb_id = 344865 ON CONFLICT (game_id, language_code) DO NOTHING;
