INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('asteka', 61939, '1984-04-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5zgw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckfya.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asteka', 'Asteka (アステカ) is an early graphical adventure game that was created by Tsuneyuki Miyamoto at Nihon Falcom. The title was initially released for the NEC PC-88 and was later ported to other Japanese computers. While exploring the Palenque ruins in southern Mexico, the player takes the role of an archeologist where they use the game''s katakana text parser to interact with the world and solve puzzles. The game was technically impressive for its time due to how quickly it could load new images, similar to Falcom''s Demons Ring, and for its use of digitized photographs for some of its graphics. Asteka was most likely released on April 13, 1985 according to early advertisements. However, even Falcom contradicts itself on the title''s exact publication date. Falcom''s official corporate timeline on their website says Asteka was released in February 1985 while their 2017 pop-up museum, along with the Falcom Chronicle anniversary book, claims it was released on April 10, 1984. A direct sequel to Asteka was released in 1986 called Temple of the Sun: Asteka II, also known as Tombs & Treasure in North America.' FROM games WHERE igdb_id = 61939 ON CONFLICT (game_id, language_code) DO NOTHING;
