INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thunder Castle', 'A whimsical new medieval fantasy game developed Connie Goldman and David Warhol of Mattel Electronics and published by INTV Corporation for the Intellivision in 1986. You''re the knight in shining armor on your quest for survival. Your journey takes you through the enchanted forest where three dragons wait with heated breath. Then, through a castle maze with three wicked wizards. Finally to a dark and dreary dungeon where the three demons present your final challenge.' FROM games WHERE igdb_id = 26296 ON CONFLICT (game_id, language_code) DO NOTHING;
