INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cutthroats', 'Cutthroats is an interactive fiction computer game written by Michael Berlyn and Jerry Wolper and was published by Infocom in 1984. Like the majority of Infocom''s games, it was released for most of the popular computer platforms of the time, such as the Apple II, DOS, Commodore 64 and several other platforms. It is Infocom''s thirteenth game.' FROM games WHERE igdb_id = 12260 ON CONFLICT (game_id, language_code) DO NOTHING;
