INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Match Point', 'Match Point is a tennis video game released in 1984–1985 for the Amstrad CPC, Atari ST, Commodore 64, ZX Spectrum and Sinclair QL by Psion and other publishers and, under the title Tournament Tennis, on ColecoVision , Commodore 64 and MS-DOS by Imagic. It was also published for Thomson TO7, Thomson MO6 and Thomson MO5 under the title Super Tennis. Some editions for Atari ST, Commodore 64 (on cartridge) and DOS used the simple title Tennis.' FROM games WHERE igdb_id = 324904 ON CONFLICT (game_id, language_code) DO NOTHING;
