INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cyclone', 14023, '1984-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/wqpccc3ss9ouymbmdoar.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/smcg0kmey8e0wxj3o2ri.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cyclone', 'The player controls a rescue helicopter and must retrieve five supply crates from a collection of islands, while a dangerous cyclone is in the area. While searching for the missing crates, the player may optionally earn bonus points by rescuing refugees from the islands. There is no limit on the number of crates or refugees the helicopter can carry, and the player only needs to return to Base Island after the last crate has been found and loaded. Hindering progress is the cyclone itself, which can cause the helicopter to behave erratically at long range, and crash at close range. While over open water the helicopter must avoid low flying planes which traverse the screen occasionally. The player also has limited fuel - which can be replenished at helipads on several of the islands - and a time limit in which to retrieve the crates. The screen display warns the player of the cyclones proximity, any approaching planes, and also the remaining time and fuel. The view has two aspects of North and South to switch between, which is necessary as some of the crates are hidden behind buildings or terrain. There is also a map view to help locate the cyclone and the islands. Once completed the game loops, with no change in difficulty. Panayi’s previous game, Tornado Low Level, (and to a lesser extent Android 2,) featured similar graphics.' FROM games WHERE igdb_id = 14023 ON CONFLICT (game_id, language_code) DO NOTHING;
