INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wizard-of-ids-wiztype', 94614, '1984-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6c3d.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wizard of Id''s WizType', 'The Wizard of Id''s WizType is an edutainment title based on the comic strip created by artist Brant Parker and writer Johnny Hart. The title is designed to give keyboard novices lessons on how to improve their typing accuracy and speed. The game is broken into two sections: The first section pits players as the Wiz, matching wits against the Evil Spirit, an apparition that lives in the Wizard''s vat. The Wizard must quickly type out the words that the Evil Spirit gives him in order to diminish the Spirit and win the round. Failure to spell words properly, or taking too long to spell results in the Evil Spirit morphing into a dragon, and singing the Wizard to a crisp. The second part of the game has the player trying to keep up with Bung the Jester. In this segment, players must type out a pre-written paragraph in order to keep pace with Bung, who is hopping along the words on a pogo stick. WizType has multiple skill levels to match different levels of typing ability, and increases in challenge as players progress through their lessons.' FROM games WHERE igdb_id = 94614 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 94614 AND ge.slug = 'quiz-trivia' ON CONFLICT DO NOTHING;
