INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ben Bero Beh', 'Ben Bero Beh is a platform game where you guide a small superhero through an apartment complex on fire! Armed with a fire extinguisher, you must make your way down the levels avoiding gas explosions, crumbling floors, damaged lighting fixtures, and various enemies that pop out of the doors. The goal is to extinguish the fire and rescue Ben''s girlfriend.' FROM games WHERE igdb_id = 40265 ON CONFLICT (game_id, language_code) DO NOTHING;
