INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vs. Wrecking Crew', 'Vs. Wrecking Crew is an arcade game for the VS. System, predating the 1985 console game Wrecking Crew. The game is less puzzle oriented, does not contain the level editor, and features a simultaneous two-player mode in which the opposing player is seen on the other side of the construction wall. In single player, Luigi acts similar to Foreman Spike and is present in all levels, while Foreman Spike is absent entirely.' FROM games WHERE igdb_id = 40533 ON CONFLICT (game_id, language_code) DO NOTHING;
