INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('donkey-kong-3-dai-gyakushuu', 56218, '1984-08-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co217q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3p4u.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donkey Kong 3: Dai Gyakushuu', 'A semi-sequel to Donkey Kong 3, using different play mechanics and a completely new set of levels. Like Mario Bros. Special and Punch Ball Mario Bros., the game is not a port, but more of a semi-sequel to Donkey Kong 3. Stanley the Bugman''s ability to jump is removed, along with the need to protect plants, making it much closer to a traditional shooter, à la Galaga. Enemies come down from the top of the screen in groups of five, swooping to the bottom and trying to target Stanley. After swooping around a bit, the enemies will exit the screen (usually from the bottom, though sometimes from the sides) and loop back around to the top. This will continue until Stanley dies, shoots Donkey Kong to the top of the screen, thus completing it, or kills the five insects, all of which take two hits apiece to kill. If Stanley kills all five insects before any of them loop back to the top of the screen, a flag reminiscent of one from Rally-X will appear, and shooting it will net him 1,000 points.' FROM games WHERE igdb_id = 56218 ON CONFLICT (game_id, language_code) DO NOTHING;
