INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'San-nin Mahjong', 'Sannin Mahjong is a mahjong game for the SG-1000. It is sometimes also known as 3-nin Mahjong, meaning three player mahjong. This number of players is not possible in either of Sega''s own versions of the game, Mahjong and Home Mahjong.' FROM games WHERE igdb_id = 45385 ON CONFLICT (game_id, language_code) DO NOTHING;
