INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Three Stooges', 'Stars of television and cinema, and now stars of their own video game. Join Moe, Larry & Curly (in no particular order) who must collect $5000 to try and save an orphanage and the young children who live there from the evil banker, all while keeping pie out of their face. Featuring platform level designs based on classic Stooge scenes from their many TV episodes and movies and level objectives re-living many of their antics plus original Stooge voices and Stooge trivia.' FROM games WHERE igdb_id = 25690 ON CONFLICT (game_id, language_code) DO NOTHING;
