INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vs. Clu Clu Land', 'Vs. Clu Clu Land is the Nintendo Vs. System (Arcade) port of Clu Clu Land (NES). In the game, two fish must swim through a maze attempting to reveal hidden gold bars while fighting against sea urchins. The game has multiplayer support for 2 simultaneous players.' FROM games WHERE igdb_id = 40512 ON CONFLICT (game_id, language_code) DO NOTHING;
