INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big Bird''s Funhouse', 'Big Bird''s Funhouse is an educational game for multiple systems. All commands are via a special EasyKey keyboard overlay. Contains 5 mini-games: - Sneak a Peek! - That''s an Order! - Watch Your Windows! - What a Runaround! - Who''s Hiding? In different activities, Muppets will pop up, and the player must remember the order that they appeared.' FROM games WHERE igdb_id = 362421 ON CONFLICT (game_id, language_code) DO NOTHING;
