INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bubble-burst--1', 362446, '1984-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coabn6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scyoi2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bubble Burst', 'Bubble Burst is a 1 - 2 player educational game for the Commodore 64. Stop the Zeboingers from bursting all the bubbles in Soapie''s bathtub. The player controls a target, and must shoot bubbles at bird-like Zeboingers as they fly towards the bubblebath. If the Zeboingers reach the bubbles, the bubbles pop, and the bath gets less bubbly. The player has limited bubble juice each round, after which they can no longer defend themselves. The Zeboingers can open the window or turn on the shower, which further reduces bubbles. Each game, the player can choose to start on round 1 or 11.' FROM games WHERE igdb_id = 362446 ON CONFLICT (game_id, language_code) DO NOTHING;
