INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'All or Nothing', 'All or Nothing is an action-adventure game for the ZX Spectrum. The mission in All or Nothing is to retrieve secret files from an enemy camp and escape, all within a time limit. The game has an isometric display that utilizes four cameras. If the character is obscured by an object, the camera will change automatically to keep the character in view.' FROM games WHERE igdb_id = 152482 ON CONFLICT (game_id, language_code) DO NOTHING;
