INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lode-runner-the-bungeling-strikes-back--1', 375137, '1984-12-31', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lode Runner: The Bungeling Strikes Back', 'The Bungeling Strikes Back is the arcade sequel to the original game, consisting of 30 levels, of which ten are based on the original set. The objective of each level is the same: collect all the gold scattered around the levels while avoiding enemies. In the event that you are trapped, you can create holes in the platforms to the left or right of you for the enemies to fall through, similar to what the player does in Apple Panic. They will then die and respawn. Some enemies will flash, letting you know that they carry gold. You can either wait for them to drop the gold or force them to give it up by trapping them in holes.' FROM games WHERE igdb_id = 375137 ON CONFLICT (game_id, language_code) DO NOTHING;
