INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Action Soccer', 'Super Action Soccer gives you the chance to be the most accomplished star player of any team that ever was. You will be the goal-keeper diving to make incredible saves, the full back with fierce last minute tackles, the mid-field "general" directing shrewd passes and the centre forward scoring great goals. You will be involved all the time in the most exciting moments of the game. You will score the winning goal! Team Pixelboy released Super Action Soccer for the North American audience.' FROM games WHERE igdb_id = 40907 ON CONFLICT (game_id, language_code) DO NOTHING;
