INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donkey Kong Hockey', 'Donkey Kong Hockey is one of the few two-player Game & Watch games ever manufactured. It was released as a part of the Micro Vs. series. Donkey Kong and Mario must engage each other in a two-player game of ice hockey. The game is colorless, being set up on a small LCD screen. The console is an elliptical shape, while the controllers are small and circular; the console can open up to store the controllers.' FROM games WHERE igdb_id = 131899 ON CONFLICT (game_id, language_code) DO NOTHING;
