INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zulu', 'Zulu is an action-maze game by Firebird Software. Players control Wyatt Hunter, sent back in time to collect 100 Golden Masks while avoiding Zulu warriors and maze hazards. Shields provide brief protection, but survival depends on quick navigation and strategy.' FROM games WHERE igdb_id = 365287 ON CONFLICT (game_id, language_code) DO NOTHING;
