INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beaky and the Egg Snatchers', 'The Andromedan Armed Condors like to lay their eggs on the planet Crackit. The hostile natives, the Egg Snatchers, don''t particularly like that and try to destroy the eggs. You are Beaky, one of the condors, who must protects his eggs.' FROM games WHERE igdb_id = 13964 ON CONFLICT (game_id, language_code) DO NOTHING;
