INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crypt-capers', 348938, '1984-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9yo0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scxfv9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crypt Capers', 'One day, while studying ancient Egyptian ruins, the player discovers an unknown pyramid buried in the sands of the Sahara. Once inside, the player must try to collect all the treasures, including: statues, old jars, papyrus, and masks. On each level the goal is to gather all the keys and reach the exit door to the next level, while avoiding dangerous snakes, fireballs, and ghosts. The player moves in the cardinal directions, and can fire their gun forwards. Dangers appear in their chamber, and then roam the halls.' FROM games WHERE igdb_id = 348938 ON CONFLICT (game_id, language_code) DO NOTHING;
