INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Best of Chess: Volume I - American Triumph', 'Best of Chess volume 1: American Triumph (1984) is interesting for being an early program with large amounts of content for learning chess. In this case, it presents games of Bobby Fischer in an interactive guess-the-move fashion. Unfortunately, I have not been able to find any good documentation.' FROM games WHERE igdb_id = 362419 ON CONFLICT (game_id, language_code) DO NOTHING;
