INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'In the Psychic City', 'An early Japanese RPG released by Hot-B in 1984 that departed from the fantasy themes of most other early RPGs in favour of what is possibly gaming''s first sci-fi cyberpunk plot. Set in a post-apocalyptic city, the game revolves around an amnesiac protagonist with psychic powers.' FROM games WHERE igdb_id = 65623 ON CONFLICT (game_id, language_code) DO NOTHING;
