INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Pipeline', 'This is an action game created by Taskset. Your job in this game is to keep a pipeline flowing with water. This pipeline will be disrupted by a falling plug from above this line. Your workman assisting you to repair the possible plugs caused. Critters are around the pipeline and will kill you if they touch you.' FROM games WHERE igdb_id = 24662 ON CONFLICT (game_id, language_code) DO NOTHING;
