INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mimi la fourmi', 'Mimi the ant is living in her little hut. Press a key on your keyboard to see her, or one of her neighbors, or even the nature around her, perform an action. A relaxing game with no objectives, though if you want, ponder which french word is being illustrated by the action. The key you pressed is the first letter of the word.' FROM games WHERE igdb_id = 387284 ON CONFLICT (game_id, language_code) DO NOTHING;
