INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alphabet Zoo', 'Alphabet Zoo is an educational maze game viewed from above, challenging players to collect letters scattered throughout the arena. Navigate the maze, use teleporters for quick travel, and race against time to complete letter-based objectives. In one mode, repeatedly collect the first letter of a displayed object, while in another, gather all letters of the object''s name in order. Enjoy solo play or compete with a friend in two-player mode. With customizable difficulty settings, including letter case options and level selection, Alphabet Zoo offers an engaging way to reinforce letter recognition and spelling skills for players of various ages and abilities.' FROM games WHERE igdb_id = 12291 ON CONFLICT (game_id, language_code) DO NOTHING;
