INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Off the Wall', 'Off the Wall is a sports game that combines elements of racquetball and tennis. The game characters are moved between the net and their rear wall with a two-position joystick. A trackwheel is used to control the paddle that hits the ball. The game may be played by one player against the computer or by two players against each other. A game is over when one player scores 11 points.' FROM games WHERE igdb_id = 333931 ON CONFLICT (game_id, language_code) DO NOTHING;
