INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bread-and-butter', 45639, '1984-02-01', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bread and Butter', 'Bread and Butter is an arcade style action game for the Sega Master System (or emulator). You run, jump, climb and float on balloons to avoid wild animals and collect the super-sized ingredients to bake the Bread of Legend.  Bread is a girl with brown hair who always wears an apron and a chef''s hat. She wants to become the greatest baker in existence and things such as danger and common sense won''t stand in her way! Butter is just a fat boy in a green shirt with blond hair who loves to eat. So he follows Bread everywhere she goes, for food is soon to follow.  It is Bread''s life goal to bake the Bread of Legend. The ingredients are rare and hidden in very dangerous places. Bread sets off without hesitation to collect the ingredients. Butter warns Bread of the dangers, but she doesn''t listen. Butter still follows, as his stomach always gets the better of him.  Collect the ingredients from 8 different stages as you go for the high score!' FROM games WHERE igdb_id = 45639 ON CONFLICT (game_id, language_code) DO NOTHING;
