INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wanted!: Monty Mole', 'Wanted: Monty Mole is a platform video game that was published in 1984 by Gremlin Graphics. Versions were released for the ZX Spectrum and Commodore 64 home computers. The player controls the titular mole who has to travel around a coal mine collecting pieces of coal and other miscellaneous objects while avoiding various nasties and the infamous crushers. The style of gameplay is typical of platform games of the 1980s. The ZX Spectrum version is a flip-screen game while the Commodore 64 version uses scrolling.' FROM games WHERE igdb_id = 26278 ON CONFLICT (game_id, language_code) DO NOTHING;
