INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rocket-roger', 40960, '1984-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8kyj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctaer.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocket Roger', 'You are Rocket Roger and on your way home to Earth, your ship has run out of fuel and you are forced to land on a mysterious planet. As you explore the planet you realize that scattered over the planet are fuel crystals and 99 are needed to refuel your ship. Problem is the locals aren''t friendly and will try to kill you as you explore the surface and underground caverns. Some can be shot with your laser but others must be avoided and if you touch one then you lose one of five lives. Turrets also need to be avoided as well as their bullets and under the planets surface are electric gates and lasers to avoid touching. As well as your gun you have a jet-pack strapped to your back and this can help you clear gaps and reach higher parts of the planet. As you fly your fuel for the jet-pack will decrease but you can collect extra to keep it topped up. Rocket Roger is a platform game where a small part of the planet is shown and the screen scrolls in all directions when you move. The keyboard is used to control your hero and as well as the main playing area you can also see your score, jet-pack fuel, best score, crystals collected, lives and which zone you are in.' FROM games WHERE igdb_id = 40960 ON CONFLICT (game_id, language_code) DO NOTHING;
