INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FlightSim I', 'FlightSim I puts the player inside the cockpit, behind the controls of a high performance jet. This game is in the conception of the Flight Simulator computer game series but for the TRS-80 Color Computer.  The simulation environment consists of approximately 22,185 square miles and recreates most of the conditions normally encountered in actual flight. The player can fly the jet to any of eight airports or nine landmarks scattered throughout the simulation area.' FROM games WHERE igdb_id = 69416 ON CONFLICT (game_id, language_code) DO NOTHING;
