INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jewels of Babylon', 'The Jewels of Babylon are a collection of gems created 3000 years ago which are now in the possession of Queen Victoria. They were to be a wedding gift to for an Indian princess but got stolen by pirates on the west coast of Africa. As a survivor of the attack you set out to find the jewels...' FROM games WHERE igdb_id = 14136 ON CONFLICT (game_id, language_code) DO NOTHING;
