INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Fantasy', 'There are eight dance steps to choose from and endless ways to put them together. You decide how long your dance is, where the dancers move, and how they dance together. And that creates the freedom children need to stretch their imaginations and create their own special works of art.' FROM games WHERE igdb_id = 40899 ON CONFLICT (game_id, language_code) DO NOTHING;
