INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cliff-hanger--1', 317146, '1984-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ut3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scty9q.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cliff Hanger', 'In the game, different scenes from a Western movie are shot. Either you play the hero "Cliff Hanger" on your own, or twosome when his brother "Coat" joins in. The aim is, to release an action at the right point of time, to "kill" the bandit "El Bandito", who runs through the screen (e. g. roll a rock, throw a boomerang, fire a canon, etc.). The scenes are chosen randomly by the program and are repeated until the action was successful. The title of the scene gives a hint to what scene will come up. The game was obviously inspired by the old Looney Toons Roadrunner and Wile E. Coyote cartoons.' FROM games WHERE igdb_id = 317146 ON CONFLICT (game_id, language_code) DO NOTHING;
