INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kong Strikes Back!', 'Kong Strikes Back! is a 1984 platform game and a clone of Mr. Do''s Wild Ride with Donkey Kong-inspired graphics. The player must rescue a damsel in distress on a rollercoaster in a fairground, and the goal of each level is to reach the top of the level to save her from Kong, a large ape. The player must avoid rollercoaster carts and various hazards by climbing up ladders on the track, and then climbing down and continuing up the track after the hazards pass.' FROM games WHERE igdb_id = 77453 ON CONFLICT (game_id, language_code) DO NOTHING;
