INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zone Ranger', 'Over 30 seperate zones of indescribable danger. Pitting you against a devastatingly evil minefield of destruction. Not to mention countless horrible enemies. Strike them and they only multiply. Detonate the deadly mines that litter your cosmos or you''ll be sorry. Find an elusive, mysterious superportal and you''ll get even. It''s intense multiscreen action. Which loosely translated, simply means, it''s awesome fun.' FROM games WHERE igdb_id = 12974 ON CONFLICT (game_id, language_code) DO NOTHING;
