INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Les Flics', 'In Les Flics, players steal the Purple Puma gem while pursued by Unspecteur Cleudeau and Gend''armerie Kaolin. Drive through a city with interconnected buildings, avoiding police cars. Inside, navigate platform stages with five levels, collect objects for the heist, and evade guards. Les Flics is inspired by the Pink Panther.' FROM games WHERE igdb_id = 254643 ON CONFLICT (game_id, language_code) DO NOTHING;
