INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ad Infinitum', 'Ad Infinitum is a side-scrolling shooter featuring single-screen gameplay across 256 levels. Players control a spacecraft, battling waves of aliens while managing weapon heat and fuel. The game includes asteroid storms, docking with motherships, and various hazards that deplete the six lives per continue. Up to four players can participate in turn-based multiplayer action, creating a challenging and dynamic space combat experience.' FROM games WHERE igdb_id = 47222 ON CONFLICT (game_id, language_code) DO NOTHING;
