INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mysterious Stones: Dr John''s Adventure', 'Mysterious Stones: Dr. John''s Adventure, known as Mysterious Stones: Dr. Kick''s Adventure in Japan, is an arcade title produced by Technos in 1984. In this game you play as the titular Dr. John, an archaeologist who travels around the world exploring temples and finding stones. Break open as many stones as possible to acquire rare artifaces while avoiding or defeating the temple guards.' FROM games WHERE igdb_id = 39717 ON CONFLICT (game_id, language_code) DO NOTHING;
