INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xonix', 'Xonix is a classic arcade-style DOS game which was probably inspired by Qix. In the game, the player controls a small marker that moves on a rectangular playfield. The goal is to claim a certain percentage of the playfield by drawing lines with the marker around areas that have not been claimed yet. The player must avoid collisions with balls bouncing around the playfield to avoid losing a life.' FROM games WHERE igdb_id = 239937 ON CONFLICT (game_id, language_code) DO NOTHING;
