INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Telly Turtle', 'Telly Turtle is basically a port of the LOGO programming language with the main character being a turtle. The keypad buttons of the Colecovision are used to issue commands from a selection presented on-screen and eventually, programs can be formed to move Telly Turtle around the screen in a series of directions. Music and Sound Effects are also added into the mix to broaden the programming experience.' FROM games WHERE igdb_id = 40905 ON CONFLICT (game_id, language_code) DO NOTHING;
