INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nebula', 'You are on the Planet NEBULA during the time of the Pharaohs in 2019. A thousand of pitfalls await you and the Gods see you when you approach their tombs. Can you use your laser beams and homing bombs to destroy them? Make no mistake, because it will be fatal! Contains four levels for one or two players.' FROM games WHERE igdb_id = 99332 ON CONFLICT (game_id, language_code) DO NOTHING;
