INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gato', 'Gato is a submarine simulator originally released for several personal computers, such as the Apple II, Atari 8-bit, and Commodore 64. Atari had plans to port GATO to the Atari 7800 and even put together a simple demo, but it doesn''t appear the game ever got beyond that stage.' FROM games WHERE igdb_id = 19702 ON CONFLICT (game_id, language_code) DO NOTHING;
