INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nebula', 'Nebula is a game of strategic galactic conflict. Players take the role of emperors attempting to expand and control star systems. The inhabitants of the systems are forced to serve their emperor but imperial conquest has its risks. War with other empires is inevitable. Unrest, revolution and plague beset the struggling empires.' FROM games WHERE igdb_id = 53395 ON CONFLICT (game_id, language_code) DO NOTHING;
