INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('macman-and-the-great-escape', 314496, '1984-03-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8pw2.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MacMan And The Great Escape', 'Meet MacMan, the canny Scot who takes children on fun-packed maths adventures. MacMan and the Great Escape teaches children about shape and area, and about the effects of rotation and reflection. MacMan is guarding some prisoners trapped behind a wall. As if by magic, holes of different shapes and sizes appear in the wall. Children help MacMan stop his prisoners escaping by selecting shapes of the appropriate area, then manipulating them by rotation and/or reflection to fit each hole. If they are too slow, the prisoners break out and terrible things happen to MacMan! The program features suberb special graphics effects, and a range of six difficulty levels. This software was developed by educationalists and has been tried and tested in schools and homes. The program was written by Intelligent Software, creators of high quality educational software. For 5-9 year olds.' FROM games WHERE igdb_id = 314496 ON CONFLICT (game_id, language_code) DO NOTHING;
