INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Family Basic', 'The Family Basic is a Basic interpreter for the Famicom that was only released in Japan. It included the Famicom Keyboard and a tape drive called the Famicom Data Recorder. Many versions were released following the first version which was released in June 1984. Version 3 included games that were based on previous Nintendo titles.' FROM games WHERE igdb_id = 220557 ON CONFLICT (game_id, language_code) DO NOTHING;
