INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('quest-for-the-holy-grail', 45247, '1984-02-01', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quest for the Holy Grail', 'The Quest for the Holy Grail falls into the genre of a text adventure game but in addition to the text there are simple pictures which help add to the descriptions of the locations you are in and add to the atmosphere as you move around the game world. You take on the role of the knight Sir Tappin, who is on a mission to track down the Holy Grail. You must navigate your way around the villages and countryside of medieval England to track down the clues that will help you on your quest. You will need to find objects to help you negotiate your way past the characters dotted along the way, such as the White Rabbit and the Knight Who Says Nic. The Quest for the Holy Grail is a trip through a possible version of history, with a liberal sprinkling of humour thrown in too.' FROM games WHERE igdb_id = 45247 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 45247 AND p.igdb_id = 26 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mr-wiz', 128447, '1984-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9jrq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7jt6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mr. Wiz', 'Mr. Wiz is a Mr. Do! variant which plays largely the same but with a few differences. The player is in control of a wizard who has to be guided around a garden while eating cherries and avoiding evil gremlins. The gremlins can be killed by either throwing a crystal ball or by making apples fall onto them. If the gremlins get frustrated or trapped they might eat the apples or dig their own passages to reach the wizard. Bonus points can be earned by eating a magic mushroom but it will at the same time enrage the gremlins and make them permanently furious. The main differences from the arcade game is that there are no alpha monsters or other enemies than the gremlins and that it is not possible to freeze their movements.' FROM games WHERE igdb_id = 128447 ON CONFLICT (game_id, language_code) DO NOTHING;
