INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tournament Tennis', 'Tournament Tennis is an early tennis game featuring or even creating many conventions that would become standard features in later tennis simulations. Matches can be played at quarter-final, semi-final or final level - winning at one level automatically moves the player to the next one. They can last for 3 or 5 sets, with a player requiring a 2-game lead to win a set, though a tie-break comes in at 6–6 in all but the final set.' FROM games WHERE igdb_id = 40904 ON CONFLICT (game_id, language_code) DO NOTHING;
