INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stock Car', 'Stock Car is an overhead-view racing video game written by A. W. Halse and published in the UK by Micro Power. It was released in 1984 for the BBC Micro, Acorn Electron, and Commodore 64 computers. Although the cassette inlay gives the release date as 1984, some sources state the release date as 1983, and the game is also known as Stock Car Racer. Stock Car is similar to Atari, Inc.''s Sprint 2 arcade game (1976) and Indy 500 for the Atari VCS (1977).' FROM games WHERE igdb_id = 228833 ON CONFLICT (game_id, language_code) DO NOTHING;
