INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocket Man', 'A unique platformer with twist. While being chased by a giant blob you need to gather fuel and a rocket on the right platform. After this you can fly, over water, to the left platforms to gather jewels. Given the capabilities of the ZX81 an wonderfull game in "high-res".' FROM games WHERE igdb_id = 152089 ON CONFLICT (game_id, language_code) DO NOTHING;
