INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crypt of Medea', 'Your courage and problem-solving ingenuity will be put to the test as you try to escape from Medea''s forbidden tomb. You must pass through countless rooms and secret passages. Overwhelming terror and ghoulish obstacles await you at every turn. You''ll need every shred of intelligence and survival skills to pass untouched from the Crypt of Medea. Escape has never been so thrilling! Autopsy of this adventure.' FROM games WHERE igdb_id = 15512 ON CONFLICT (game_id, language_code) DO NOTHING;
