INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Traffic', 'Traffic is a flick-screen game where you have to move across lanes full of various vehicles for as many points as you can. The vehicles move left or right across the screen and you have to move upwards through gaps while avoiding getting hit by the vehicles or it is game over. If you move downwards then your score decreases. There are 3 skill levels and you can choose the speed of the game (1-255) with 1 being the fastest.' FROM games WHERE igdb_id = 319601 ON CONFLICT (game_id, language_code) DO NOTHING;
