INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kinkey Dong', 'This Donkey Kong clone is published as a type-in listing in the book “Sensational Games for the Amstrad CPC 464”. The book was published by Collins and Jim Gregory wrote the game. The game also a re-pumping published as a type-in listing in the Greek magazine Pixel n° 47 - September 1988, with Stathis SDRALIS and Petros ATHANASIOU handling the re-pumping. In 2019, a revised and improved version was released as a homebrew release.' FROM games WHERE igdb_id = 275225 ON CONFLICT (game_id, language_code) DO NOTHING;
