INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tube Panic', 'Tube Panic was produced by Nichibutsu in 1984. Nichibutsu released 80 different machines in our database under this trade name, starting in 1979. Other machines made by Nichibutsu during the time period Tube Panic was produced include Roller Jammer, Pastel Gal, Ninja Emaki, Dangar Ufo Robo, Cop 01, Dacholer, Skelagon, Nichibutsu Hustler, Rug Rats, and Constella.' FROM games WHERE igdb_id = 40163 ON CONFLICT (game_id, language_code) DO NOTHING;
