INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('stuart-smiths-adventure-construction-set', 2416, '1984-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5iq0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/t3cehng60bnqo9gwl72c.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stuart Smith''s Adventure Construction Set', 'Play 8 great adventures... Or write your own. Rivers of Light- A new Stuart Smith epic. Set at the dawn of human history in Ancient Egypt and the Near East, this new epic adventure from the author of Ali Baba and Return of Heracles embraces a map containing over 140 different regions and rooms, plus a cast of hundreds and enough challenging and ingenious puzzles to delight even the most demanding adventurer. 7 complete mini adventures: There''s a simple tutorial adventure for first timers, plus one mystery story, one original adaptation from Alice In Wonderland, a historical drama (you help Washington cross the Delaware), and 3 more called Deep Dark Dungeon, In the Nazi Castle, and Save the Galaxy. 3 basic construction sets included: You get a Fantasy Set, a Spy/Mystery Set and a Science Fiction Set. Each comes with graphics, music and sound effects, a wardrobe full of creature and character costumes, and a prop room crammed with objects and special effects. Do as much or as little work as you like. Build the whole adventure yourself of ask the computer to do it for you. A canvas as big as your imagination: Each adventure can contain up to 500 different creatures, one main map and up to 15 map regions with up to 16 rooms and 300 props per region, plus up to 335 different text messages to give your adventures texture and depth. Use the parts in the 3 basic construction sets or make your own.' FROM games WHERE igdb_id = 2416 ON CONFLICT (game_id, language_code) DO NOTHING;
