INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turmoil', 'Bug Byte''s Turmoil is a platform game where Mick The Mechanic steals the sheik''s cars, collecting oil while avoiding Arabian bodyguards. Through 26 screens with hazards like springboards and disappearing walls, Mick''s goal is to pour oil into the grid, gradually revealing and increasing the value of the hidden cars. Special bonuses can be obtained by collecting tools.' FROM games WHERE igdb_id = 47153 ON CONFLICT (game_id, language_code) DO NOTHING;
