INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Word Games with the Mr. Men', 'These educational games with the Mr. Men characters from Roger Hargreaves'' children books are for kids aged 5 to 8 years. It features these fun games that also develop reading skills: * Mr Noisy''s Word Game - Learn about opposites, comparatives and superlatives. There are nine different games to play, each of which can be selected from the main menu. Other games allow various combinations of reading and writing exercises ranging from matching up a picture with the correct word to choosing the opposite to a displayed word.' FROM games WHERE igdb_id = 97796 ON CONFLICT (game_id, language_code) DO NOTHING;
