INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('snail-against-squirrel', 40696, '1984-01-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ymd.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snail Against Squirrel', 'Would you kindly help a little squirrel whom often you found playing in the woods? I am a very, very friendly squirrel; I swear, I never intend to hurt that poor snail. As it becomes colder and colder, I want nothing more than to store some nuts in my caves, lest I should be no more after the winter. But why in the world is that greedy snail always hiding somewhere to rob me of my nuts, just like those highway men? See what a dilemma I am involved in? To keep away from that cunning snail, should I go on carry the nut to my cave or gather a newly ripe one?' FROM games WHERE igdb_id = 40696 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 40696 AND p.igdb_id = 59 ON CONFLICT DO NOTHING;
