INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mr. Ching', 'Clad in Chinese clothes and wearing a Chaplin moustache our hero, Mr. Ching, China''s proud plate-spinner hustles onto the stage! Five or six plates are kids stuff. How many plates can you make him spin even with interference from rascals, and the naughty plates which tend to fall... You will receive a standing ovation if you turn all the plates. A thrilling yet comical game sure to attract your heart!' FROM games WHERE igdb_id = 41788 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 41788 AND p.igdb_id = 27 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('clear-for-action', 24675, '1984-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8hik.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scszyt.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clear for Action', 'Ship-to-ship combat in the days of sail. You play against the computer, with your ship at the bottom of the screen. The enemy ship soon appears at or around the top of the screen. Once sited, the computer announces ''Clear for Action!'' in large text. You maneuver your ship, as does the computer, to acquire the best angle for a broadside, using the wind to best advantage. You have a choice of solid, grape or chain shot, depending if you want to damage the sails, the hull, or the men. After some exchange of cannon fire, the ships then grapple and attempt to board the enemy ship for combat with the crew, with the winner typically having the most crew to begin with, taking into account experience.' FROM games WHERE igdb_id = 24675 ON CONFLICT (game_id, language_code) DO NOTHING;
