INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bouncing Babies', 'Bouncing Babies is a computer game developed in 1984 by Dave Baskin for MS-DOS. The player is in control of a two-man team of fire fighters who rescue babies thrown from the windows of a building in flames into a bouncing stretcher and safely into an ambulance.' FROM games WHERE igdb_id = 46652 ON CONFLICT (game_id, language_code) DO NOTHING;
