INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Two Tigers', 'Two Tigers is an arcade game created by Bally Midway and released in 1984. It is themed around World War II-era planes attempting to sink military ships, but there are no references as to which countries are involved in the conflict. Two Tigers offers the choice of two separate modes: one or two players working together to sink large enemy ships, or a dogfight mode where two players attempt to down each other''s plane.' FROM games WHERE igdb_id = 25667 ON CONFLICT (game_id, language_code) DO NOTHING;
