INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Falcon Patrol 2', 'Just like in "Defender" the player can move in both horizontal directions while a radar shows him the enemy''s positions and landing platforms where the jet can be refueled and rearmed. 15 levels must be completed in order to rid the world of evil. The player only progresses to the next stage when a certain amount of helicopters are shot down.' FROM games WHERE igdb_id = 18963 ON CONFLICT (game_id, language_code) DO NOTHING;
