INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Polar Pierre', 'A single-screen 2D platformer in which up to two players can compete with each other. The object of the game is for each player to maneouvre his character (Pierre or his cousin Jacques) through each screen, raisng all his flags along the way and then reach as quickly as possible the finish.' FROM games WHERE igdb_id = 24676 ON CONFLICT (game_id, language_code) DO NOTHING;
