INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Below the Root', 'Below the Root is an adventure game released in 1984 by Windham Classics, a division of Spinnaker Software. It is titled after Below the Root, the first of the Green Sky Trilogy of novels, written by Zilpha Keatley Snyder and published between 1975 and 1977. It is an early example of what later became known as the Metroidvania genre.' FROM games WHERE igdb_id = 13813 ON CONFLICT (game_id, language_code) DO NOTHING;
