INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sentinel', 'Sentinel is the sequel to Dimension X, you join the warriors of Dimension X to continue fight against evil on the planet Jaraloba. This time it is flown in outer space, while you are controlling the space jet. Gorganitor squadrons were detected in all 50 sectors (10x5 matrix) of your star cluster, and you should clear them one-by-one.' FROM games WHERE igdb_id = 153840 ON CONFLICT (game_id, language_code) DO NOTHING;
