INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Z-Xtricator', 'A Defender like (right only) side scrolling shooter. You are equiped with a laser to shoot enemies and a few super bombs destroying all enemies. While fighting of enemies you have to rescue prisoners on the ground by flying close to them (whatch for gravity pulling you down). This "high-resoluation" game runs on a standard ZX81 with a 16K memory expansion module.' FROM games WHERE igdb_id = 153505 ON CONFLICT (game_id, language_code) DO NOTHING;
