INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Suspect', 'Suspect is an interactive fiction computer game designed by Dave Lebling and published by Infocom in 1984. It is the last murder mystery Infocom released, bringing an end to a popular genre of titles such as Deadline and The Witness. Like most Infocom titles, it was written in highly portable ZIL and made available for an array of popular computer platforms, including the Apple II, IBM PC, Atari ST, and Commodore 64. It is Infocom''s fifteenth game.' FROM games WHERE igdb_id = 12625 ON CONFLICT (game_id, language_code) DO NOTHING;
