INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-ancient-art-of-war', 14600, '1984-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21ih.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctxc5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Ancient Art of War', 'The Ancient Art of War is a computer game developed by Evryware and published by Broderbund in 1984. In retrospect, it is generally recognized as one of the first real-time strategy or real-time tactics games. A battlefield simulation, the game''s title comes from the classic strategy text The Art of War written by Sun Tzu around 400 B.C. The objective of the game is to win a series of battles using four types of troops: Knights, Archers, Barbarians, and Spies. All four types are unmounted. It uses the simple "Rock-Paper-Scissors" type of unit balance typical of the genre. Knights beat Barbarians in melee; Barbarians have the advantage over Archers; and Archers have the advantage over Knights, in addition to being effective at defending against attempts to storm a fort. Spies did not fight, but had twice the range of any other unit type in terms of lifting the fog of war. At the start of the game, the player is able to select from a list of campaigns to play. The campaigns include both skirmishes and "capture the flag(s)" type missions, while the terrain layout and initial starting units provided a variety of strategic options for game play. Advanced rule sets such as Training New Units and Supply Line Lengths allow for more customization. The player can also select from among several Artificial Intelligence opponents represented by various historical figures such as Geronimo and Napoleon. Sun Tzu represents the most difficult level. These settings affected both AI behavior, as well as certain properties such as the speed at which enemy units moved through difficult terrain. There is no element of the economic management (mining, gathering or construction) which is a common feature of later real-time strategy games.' FROM games WHERE igdb_id = 14600 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 14600 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
