INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gremlins--1', 314530, '1984-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8pyg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctp84.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gremlins', 'The Atari 2600 adaption of the 1984 film, "Gremlins". In this version, on the first screen, Mogwai are jumping from the roof to get at hamburgers on the ground. You, as Billy, must catch them before the hit they ground. If you get them all, it is off to the next, faster, level. If you miss eight, then you go to a shooting screen. On the shooting screen, gremlins are approaching from the distance. You must shoot them before they reach you. If one reaches you, you lose a life. After they are all dead, it is back to the first screen at a faster level. In later levels, puddles of water will divide the gremlins in two. A different version of the same name was also released for the 5200, Commodore 64 and Apple II.' FROM games WHERE igdb_id = 314530 ON CONFLICT (game_id, language_code) DO NOTHING;
