INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mobile Suit Gundam: Last Shooting', 'Released in 1984, Mobile Suit Gundam: Last Shooting is the first game to be based on the Mobile Suit Gundam franchise. In the first level you have to dodge falling debris. If you''ve dodged enough debris the door of your Mobile Suit will open. Enter your Mobile Suit to proceed to the next level. In the second level you, as a pilot in your own Mobile Suit, have to shoot enemy battle mechs and gun emplacements.' FROM games WHERE igdb_id = 69763 ON CONFLICT (game_id, language_code) DO NOTHING;
