INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Battle Road', 'The Battle-Road is a vertical scrolling shooter racing arcade game released by Irem in 1984. The game was an early open-ended vehicle combat game that featured branching paths and up to 32 possible routes. The player controls a car that is armed with two different types of guns, and drives for a road full of other dangerous vehicles like cars, motorcycles, trucks, helicopters.' FROM games WHERE igdb_id = 39617 ON CONFLICT (game_id, language_code) DO NOTHING;
