INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mr-dos-wild-ride', 24630, '1984-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ung2puyco96ep4egkbjq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsntj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mr. Do''s Wild Ride', 'Mr. Do!''s scenario is a roller coaster, and the object is to reach the top. As the cars (and eventually other objects) speed around the track, you must escape by using a super speed button, or by climbing up small ladders scattered about the track. Two icons at the end of the level range from cakes to EXTRA letters or diamonds change upon collecting cherries at the top of each letter. The game is timed, and the timer ticks faster when the super speed button is depressed.' FROM games WHERE igdb_id = 24630 ON CONFLICT (game_id, language_code) DO NOTHING;
