INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Babaliba', 'Babaliba es un videojuego del género videoaventura desarrollado y distribuido por Dinamic Software en 1984, para el Sinclair ZX Spectrum. Se vendió a un precio de 1.800 pesetas. Fue comercializado en Inglaterra por Silversoft' FROM games WHERE igdb_id = 45339 ON CONFLICT (game_id, language_code) DO NOTHING;
