INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pirate-ship-higemaru', 40092, '1984-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3pos.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6k8o.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pirate Ship Higemaru', 'The player controls a Norwegian sailor by the name of Momotaro, who must use barrels to defeat the titular pirate crew. Momotaro has no attacks of his own. However, he has the ability to grab barrels, drums, large bags, and various other items which he can throw (either horizontally or vertically) across the screen. Any pirate who stands in the way of a barrel or other object will be hurled off the screen. Barrels that impact the walls of a stage or other barrels or objects will shatter and produce points, while other objects are invulnerable (but do not produce points). Each successive enemy that is hit by a barrel will yield additional points once the barrel is destroyed. In addition, there are also various items hidden beneath barrels in each level which will give Momotaro bonus points. Every floor of the ship has a set number of pirates to be destroyed, as well as a single "Bow", a special pirate that regenerates each time it is defeated. Every fourth level in the game yields a bonus level in which the barrels are worth an increased number of points, and a group of enemies entirely made up of Bows (which do not regenerate in this case). With each successive floor, the speed and intelligence of the pirates increases. For every sixteen barrels Momotaro destroys, he will be rewarded with an item that grants invincibility for a limited amount of time, allowing him to defeat enemies by simply touching them. Momotaro''s enemies do not have attacks, but a single touch from an enemy will cause him to die and be revived, costing the player one of his/her extra lives; the game will be over when he or she has no more lives. The game has no ending, but following the sixteenth level, the enemy patterns will reset to level one. The layout of the barrels on the stages will continue to change, however, and the enemy count per level will not reset to level one counts. Following level 16, the game may Kill screen at the start of a level or after losing a life.' FROM games WHERE igdb_id = 40092 ON CONFLICT (game_id, language_code) DO NOTHING;
