INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Journey to the Centre of the Earth', 'The game has no real narrative. The introduction simply places the player in the role of an unnamed explorer who must delve into a subterranean labyrinth to locate 11 hidden treasures and return them to the surface.' FROM games WHERE igdb_id = 191287 ON CONFLICT (game_id, language_code) DO NOTHING;
