INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pitfall--2', 139891, '1984-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7cqm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8nli.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pitfall', 'How deep can you go? In Pitfall you manoeuvre your ship down a seemingly neverending shaft while avoiding the rock edges and disembodied faces. Use the left right keyboard keys to move your ship side-to-side and use the up and down arrows to slightly speed your ship up or slow it down. Hitting rock faces will take points off your hit-points but hitting those creepy floating faces will mean instant death. Your ASCII graphics ship has ten hit points to start with. Five additional points are rewarded as you manoeuvre further down deeper into the shaft every three thousand points. Occasionally you will find a floating star in the depths which will reward you a bonus of two hundred points. There are no multiple attempts down the shaft. Each destroyed ship means you must start all over again.' FROM games WHERE igdb_id = 139891 ON CONFLICT (game_id, language_code) DO NOTHING;
