INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Bagman', 'The objective of the game is to maneuver the bagman through various mine shafts, picking up money bags and placing them in a wheelbarrow at the surface of the mine. The player must avoid pursuing guards, moving ore carts, and descending elevators. The player may temporarily stun the guards by striking them with a pickaxe or by dropping money bags on them when they are below the player on the same ladder. The player may move between the three screens which make up the level via shafts and on the surface.' FROM games WHERE igdb_id = 40003 ON CONFLICT (game_id, language_code) DO NOTHING;
