INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1994 (Ten Years After)', 'A videogame "sequel" to George Orwell''s speculative novel "1984". 1994 consists of basic platforming gameplay and chronologically takes place ten years after the events of the book.' FROM games WHERE igdb_id = 70295 ON CONFLICT (game_id, language_code) DO NOTHING;
