INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'High Way Star', 'With its multi-level intersections and 90 degree turns, this is a future country town. In your "Tomato" car you must obey the directions shown on the map and clear as many white flags as possible. But be careful! The skull chasing you is the skull of death and the bad guys in black are always after you. Look out--if you spend too much time escaping you run out of gas.' FROM games WHERE igdb_id = 41804 ON CONFLICT (game_id, language_code) DO NOTHING;
