INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Taxi', 'Space Taxi is a 1984 arcade-style game where players control a flying taxi, ferrying passengers between various pads across 25 unique levels. Each level presents different obstacles and challenges to navigate. The game mechanics revolve around time management and fuel conservation, as players earn more money for quicker deliveries and must avoid running out of fuel to prevent crashing. The space-themed setting and taxi service concept combine to create a distinctive gameplay experience.' FROM games WHERE igdb_id = 24510 ON CONFLICT (game_id, language_code) DO NOTHING;
