INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Golf', 'The course has 18 holes and a total length of 5,805 meters. You have to get the ball into the hole with a minimum of strokes, despite the wind and many obstacles. You can choose the club, the direction and the force with which the ball will be sent. Challenge your friends, one to four people can play together.' FROM games WHERE igdb_id = 109212 ON CONFLICT (game_id, language_code) DO NOTHING;
