INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yokai Tantei Chima Chima', 'Youkai Tantei Chima Chima is an arcade game similar to Pac-Man. In this game players will control a cyclops called Chima Chima who will fight against ghosts. In order to defeat the ghosts, Chima Chima shoots bouncing fireballs. These fireballs move together with the protagonist and can kill him so players will need to avoid enemies and have the fireballs explode next to them.' FROM games WHERE igdb_id = 138872 ON CONFLICT (game_id, language_code) DO NOTHING;
