INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Formula 1 Simulator', 'In this simulation you can race ten international circuits (only one for the C16), including traditional favourites such as Monza, Monaco and Silverstone plus no-longer-used circuits like Zandvoort and the Österreichring. This can be done in wet or dry, and with manual or automatic gears. Expect to have to drive realistically in terms of braking points and acceleration levels to set a quality lap. The Spectrum version includes a ''steering wheel'' control option, using a small disc along the top of the keyboard, using the keys for progressive steering intensity.' FROM games WHERE igdb_id = 12998 ON CONFLICT (game_id, language_code) DO NOTHING;
