INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('duck-shoot', 46899, '1984-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co93a5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar29i1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Duck Shoot', 'Duck Shoot recreates the classic fairground shooting gallery experience in a digital format. Players control a gun at the bottom of the screen, aiming to shatter six plates positioned at the top while navigating four rows of moving targets in between. The game challenges players to balance their primary objective of breaking plates with the opportunity to score bonus points by hitting other moving objects. Adding to the challenge, ducks periodically swoop down, depleting the player''s limited ammunition if they reach the bottom. A special duck traversing the top of the screen can restore shot plates if it completes its journey, introducing a strategic element to the gameplay. The game continues until the player exhausts their ammunition, which is visually represented by a bar beneath the gun, creating a constant tension between accuracy and resource management.' FROM games WHERE igdb_id = 46899 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 46899 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
