INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('moto-crash-plus', 41565, '1984-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4b8i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc83x6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moto-Crash +', 'Moto-Crash + is a motorcycle racing game. The goal is to drive as far as possible within the time limit of three minutes. The game features 4 predefined circuits (selected with the keys 1 to 4 at the start of the game) plus one random circuit generated by the computer (selected with the 0 key). The conditions of each circuit change as the player progresses. The race starts during daytime; once the player drives 6 km the night falls; at 10 km, the road becomes wet; at 20 km, the road becomes snowy and at 30 km the road becomes icy. Changes in weather conditions are not only accompanied by graphical changes but also gameplay ones, as the motorcycle''s adherence to the road changes. If the player drives 6 km in daytime or 4 km in nighttime in any weather condition without crashing the computer awards him or her a bonus time.' FROM games WHERE igdb_id = 41565 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 41565 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
