INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('son-of-blagger', 47238, '1984-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co40r5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scedsi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Son of Blagger', 'Relive the daring exploits of Roger the Dodger through his prodigy Slippery Sid. More skill, more nerve, this cool little character seeks not only to follow in his famous parent''s footsteps, but to establish some amazing feats of his own. Money''s not his game. Espionage is his middle name and having forced his way into the National Securitys HQ he''s faced with a no return journey through one of the most dangerous, most complex buildings in the land. Can he successfully complete a nerve tingling search for the golden keys - his only means of escape - or this time has his skill and daring taken him to far. Watch out for those weird killer security guards - you never what chilling surprises the mad scientists have produced - and beware the floor doesn''t disappear from under your feet, sending you to an early grave. You polished up your skills on Blagger now put them to test on his son.' FROM games WHERE igdb_id = 47238 ON CONFLICT (game_id, language_code) DO NOTHING;
