INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chicken Shift', 'The gameplay in Chicken Shift is relatively simple. There will be a string of eggs you have to guide to safety by shifting the position of pipes, walls and other devices through button presses. The default settings map the action buttons to the left CTRL and left ALT keys. Keep your eyes on those eggs and where they''re at - you''ll get bonus points if you don''t lose a single egg to the horrors of gravity.' FROM games WHERE igdb_id = 40023 ON CONFLICT (game_id, language_code) DO NOTHING;
