INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('slurpy', 25712, '1984-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ebqskteuqz10swntojow.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsvh5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slurpy', 'You control a strange green blob of a creature with a long trunk sticking out the front, moving it around in a one-screen, non-scrolling, open cave. In every level, your goal is to eat ten floating seeds. Meanwhile, of course, the game does its best to prevent you from doing so, by throwing a multitude of different monsters against you. Fortunately nearly every monster in the game can be eaten as well. If an enemy touches Slurpy, you can kiss one of your precious lives goodbye; but woe to the enemy that strays in front of Slurpy''s trunk and is caught by his amazing suction power!' FROM games WHERE igdb_id = 25712 ON CONFLICT (game_id, language_code) DO NOTHING;
