INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fiends', 'A single-screen space shoot''em up in which the player has to destroy aliens while saving some scientists. It was originally released as "Space Fiends" by Magnificent 7 in a compilation called "Liberator / Space Fiends" in 1986 for Commodore 16. In 1987 Alternative Software named it "Fiends" and re-released it as a single game.' FROM games WHERE igdb_id = 83299 ON CONFLICT (game_id, language_code) DO NOTHING;
