INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vulgus', 'This was Capcom''s first arcade game. The player controls a spaceship with a single objective: destroy incoming enemies. The vessel has two different weapons: a primary weapon with infinite ammunition and a limited supply of bombs. By picking up the "Pow" icons, which sporadically appear throughout the levels, the player can replenish supplies. [wikipedia]' FROM games WHERE igdb_id = 25886 ON CONFLICT (game_id, language_code) DO NOTHING;
