INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deus Ex Machina', 'Deus Ex Machina is a 1984 ZX Spectrum and Commodore 64 surrealistic game with a heavy focus on sensory experience above interactive gameplay. You play a defect - a human form that has formed within an all controlling A.I. While the defect police is after you, your humanlike Alter Ego transforms through several stages of a human being. While the game does not offer any audio, the story is progressed through the narrative on the audio cassette which accompanies the game and has a running time of roughly 45 minutes - the amount of time the game is meant to play in one sitting.' FROM games WHERE igdb_id = 26432 ON CONFLICT (game_id, language_code) DO NOTHING;
