INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ice-hunter', 76249, '1984-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/norkmvgzujuhb1ytroqy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/h9vlqutsykmsnetto0u2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ice Hunter', 'Ice Hunter is a single screen platformer where you play the role of Thorak the Eskimo, Prince of Ice, who is searching for blocks to make a special igloo. Finally in his search, Thorak has found a multi-level cave containing the blocks he needs for the igloo, so enters to retrieve them. The only way to get the blocks to his site for the igloo is to get two blocks, one at a time to a stream at the bottom of the cave, then stand on them to float down the stream. The main problem though is the creatures that move around the screen and these have to be avoided or if touched he loses one of four lives. The creatures though can be killed by dropping a block on top of them or allowing them to fall through the gaps. A bird that occasionally appears can be killed if its flight path is blocked.  To get the blocks to the bottom of the screen there are platforms over gaps and to get a gap Thorak can walk on the platform to remove it then drop blocks through the gap to the level below. Thorak can''t fall through the gaps or he is killed but there are pillars that can be climbed up or down. At a certain level in the cave, Thorak can''t get back up so he has to make sure he has two blocks to move to the stream. A power-pill can be collected and these stuns the creatures which can be touched to remove them. Once the blocks are floated away then it''s off to the next cave with more creatures and the levels start to scroll slowly to the left and appear again on the right of the screen.' FROM games WHERE igdb_id = 76249 ON CONFLICT (game_id, language_code) DO NOTHING;
