INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Peetan', 'Peetan is a classic puzzle-adventure game for the Game Boy and MSX. Players control a character named Peetan, who embarks on a thrilling journey through various levels filled with challenging puzzles and obstacles. The game combines elements of platforming, problem-solving, and exploration, offering an engaging gameplay experience.' FROM games WHERE igdb_id = 41786 ON CONFLICT (game_id, language_code) DO NOTHING;
